"use client";

import { useEffect, useId } from "react";
import {
  AlertCircle,
  ArrowRight,
  Bot,
  ExternalLink,
  GitBranch,
  GitPullRequest,
  Layers,
  User,
  X,
} from "lucide-react";
import type { LogEntry, ParsedTask } from "@/services/yaml-parser";
import { formatTimestamp } from "@/lib/time";
import {
  formatStatusLabel,
  getStatusStyle,
  type StatusBadgeStyle,
} from "../../lib/status";

export type TaskDetailSheetProps = {
  task: ParsedTask | null;
  featureTitle?: string;
  repository?: string;
  nextAction?: string;
  onClose: () => void;
};

export function TaskDetailSheet({
  task,
  featureTitle,
  repository,
  nextAction,
  onClose,
}: TaskDetailSheetProps) {
  const open = task !== null;
  const titleId = useId();
  const descId = useId();

  useEffect(() => {
    if (!open) return;
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("keydown", handleKey);
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", handleKey);
      document.body.style.overflow = previousOverflow;
    };
  }, [open, onClose]);

  return (
    <div
      aria-hidden={!open}
      className={
        "fixed inset-0 z-40 " +
        (open ? "pointer-events-auto" : "pointer-events-none")
      }
    >
      <button
        type="button"
        aria-label="Close task detail"
        tabIndex={open ? 0 : -1}
        onClick={onClose}
        className={
          "absolute inset-0 cursor-default bg-black/80 transition-opacity duration-200 " +
          (open ? "opacity-100" : "opacity-0")
        }
      />
      <aside
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={descId}
        className={
          "absolute right-0 top-0 flex h-full w-full flex-col bg-surface shadow-xl transition-transform duration-200 ease-out " +
          "sm:max-w-md md:max-w-lg lg:max-w-xl " +
          (open ? "translate-x-0" : "translate-x-full")
        }
      >
        {task ? (
          <TaskDetailContents
            task={task}
            featureTitle={featureTitle}
            repository={repository}
            nextAction={nextAction}
            onClose={onClose}
            titleId={titleId}
            descId={descId}
          />
        ) : null}
      </aside>
    </div>
  );
}

type ContentsProps = {
  task: ParsedTask;
  featureTitle: string | undefined;
  repository: string | undefined;
  nextAction: string | undefined;
  onClose: () => void;
  titleId: string;
  descId: string;
};

function TaskDetailContents({
  task,
  featureTitle,
  repository,
  nextAction,
  onClose,
  titleId,
  descId,
